-- The festival grounds (Devin, 2026-10-09: festivals named for every artist).
-- Compiled from Wikipedia and the festivals' own pages: name, other spellings,
-- the grounds and stage names as setlist.fm and the press print them, city,
-- region, country, the months it runs, the years it has run. A night on one of
-- these grounds in one of those months is that festival (see 0103).

-- The matcher, sharpened for the way the table reads: a grounds field may hold several
-- places with years in brackets ("Champions Park (2014-2017); Highland Festival Grounds
-- (2019-)"), so each place is cut out, cleaned of years and brackets, and a night matches
-- when its venue contains the place or the place contains the venue; short or generic
-- words ("Park", "Stage", "Arena") never match on their own.
create or replace function public.festival_grounds_match(v text, c text, cc text, d date)
returns text
language sql stable as $$
  with g as (
    select fg.*, btrim(regexp_replace(regexp_replace(t, '\([^)]*\)|\b(19|20)\d{2}(\s*[-–]\s*((19|20)\d{2})?)?|\b(and|cancelled|canceled|for rain|since|from|to|only|various|touring)\b', ' ', 'gi'), '\s+', ' ', 'g')) as place
      from festival_grounds fg, unnest(regexp_split_to_array(fg.grounds, '\s*[,;]\s*|\s+and\s+')) t
  )
  select g.name || ' ' || extract(year from d)::int
    from g
   where d is not null
     and length(g.place) >= 6
     and lower(g.place) not in ('park', 'stage', 'arena', 'grounds', 'festival grounds', 'fairgrounds', 'showgrounds', 'amphitheater', 'amphitheatre', 'main stage', 'second stage')
     and (g.country_code = '' or g.country_code = coalesce(cc, ''))
     and (cardinality(g.months) = 0 or extract(month from d)::int = any (g.months))
     and (g.first_year is null or extract(year from d)::int >= g.first_year)
     and (g.last_year is null or extract(year from d)::int <= g.last_year)
     and (lower(coalesce(v, '')) like '%' || lower(g.place) || '%'
          or (length(coalesce(v, '')) >= 8 and lower(g.place) like '%' || lower(v) || '%'))
     and (g.city = '' or lower(coalesce(c, '')) = lower(g.city) or lower(coalesce(v, '')) like '%' || lower(g.city) || '%'
          or lower(g.place) like '%' || lower(coalesce(c, '')) || '%')
   order by (lower(coalesce(c, '')) = lower(g.city)) desc, length(g.place) desc
   limit 1
$$;
revoke all on function public.festival_grounds_match(text, text, text, date) from public, anon, authenticated;

-- Tagging, with the grounds used only where they cannot mislead: a night with no tour label, a
-- night whose label is itself a festival, or a night on a named stage ("Decibel Stage") — never
-- a tour night at a hall the festival also uses some other week.
create or replace function public.festival_tag(a_id uuid)
returns int
language plpgsql volatile security definer set search_path = public as $$
declare n int := 0; k int;
begin
  update artist_history_shows h set festival = h.tour
   where h.artist_id = a_id and h.festival = '' and h.tour <> ''
     and public.tour_is_festival(h.tour) and not public.tour_find_madeup(h.tour);
  get diagnostics k = row_count; n := n + k;
  update artist_history_shows h set festival = c.name
    from tour_candidates c
   where h.artist_id = a_id and h.festival = '' and c.artist_id = a_id and c.status = 'added' and c.name <> ''
     and public.tour_is_festival(c.name) and not public.tour_find_madeup(c.name)
     and exists (select 1 from jsonb_array_elements(c.dates) x
                  where (x ->> 'date') ~ '^\d{4}-\d{2}-\d{2}$' and (x ->> 'date')::date = h.date);
  get diagnostics k = row_count; n := n + k;
  update artist_history_shows h set festival = public.festival_grounds_match(h.venue, h.city, h.country_code, h.date)
   where h.artist_id = a_id and h.festival = ''
     and (h.tour = '' or public.tour_is_festival(h.tour) or h.venue ~* '\mstage\M')
     and public.festival_grounds_match(h.venue, h.city, h.country_code, h.date) is not null;
  get diagnostics k = row_count; n := n + k;
  return n;
end $$;
revoke all on function public.festival_tag(uuid) from public, anon, authenticated;

notify pgrst, 'reload schema';
